# Use pysat to check 3-colorability
from pysat.solvers import Glucose3

def check_3_colorable(adj, n):
    # Variables: color[i][c] = i*n + c + 1 (1-indexed)
    # i in [0, n-1], c in [0, 2]
    solver = Glucose3()

    # Each vertex has at least one color
    for i in range(n):
        solver.add_clause([i*3 + 1, i*3 + 2, i*3 + 3])

    # Each vertex has at most one color
    for i in range(n):
        for c1 in range(3):
            for c2 in range(c1+1, 3):
                solver.add_clause([-(i*3 + c1 + 1), -(i*3 + c2 + 1)])

    # Adjacent vertices have different colors
    for u in range(n):
        for v in adj[u]:
            if u < v:
                for c in range(3):
                    solver.add_clause([-(u*3 + c + 1), -(v*3 + c + 1)])

    result = solver.solve()
    if result:
        model = solver.get_model()
        colors = []
        for i in range(n):
            for c in range(3):
                if model[i*3 + c] > 0:
                    colors.append(c)
                    break
        return True, colors
    return False, None

sat, colors = check_3_colorable(adj, n)
print(f"3-colorable: {sat}")
if sat:
    print(f"Colors: {colors}")
